let bpSocialCodes=[],bpSocialNotices=[],bpSocialBusy=false;
const bpById=id=>document.getElementById(id);
const bpSocialAdmin=()=>typeof adminBearer==='string'&&adminBearer.length>30;
const bpSocialMsg=(id,msg)=>{bpById(id).textContent=String(msg)};
function bpSocialDateValue(value){
 const d=new Date(value);if(!Number.isFinite(+d))return '';
 const local=new Date(+d-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,16);
}
function bpSocialResetDates(prefix){
 bpById(prefix+'Start').value=bpSocialDateValue(Date.now()-60000);
 bpById(prefix+'End').value=bpSocialDateValue(Date.now()+30*86400000);
}
function bpSocialIso(id){
 const time=new Date(bpById(id).value).getTime();
 if(!Number.isFinite(time))throw Error('日時を入力してね');return new Date(time).toISOString();
}
function bpSocialDateText(v){const d=new Date(v);return Number.isFinite(+d)?d.toLocaleString('ja-JP',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'日時不明'}
function bpSocialNode(tag,className,text){const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=String(text);return el}
async function bpSocialApi(path,{body,admin=false}={}){
 const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),60000);
 try{
  const response=await fetch(ONLINE_ORIGIN+path,{method:body?'POST':'GET',cache:'no-store',mode:'cors',signal:controller.signal,
   headers:{...(body?{'Content-Type':'application/json'}:{}),...(admin?{'Authorization':'Bearer '+adminBearer}:{})},
   ...(body?{body:JSON.stringify(body)}:{})});
  let data;try{data=await response.json()}catch{throw Error('サーバーの応答を読み取れないよ')}
  if(!response.ok)throw Error(data?.error||'通信エラー HTTP '+response.status);
  return data;
 }catch(e){if(e?.name==='AbortError')throw Error('サーバーが応答しないよ。もう一度試してね');throw e}
 finally{clearTimeout(timeout)}
}
