 bpById('bpCodeAdminId').value='';bpById('bpCodeAdminCode').value='';bpById('bpCodeAdminCode').readOnly=false;
 bpById('bpCodeAdminNote').value='';bpById('bpCodeAdminCoins').value='50';bpById('bpCodeAdminLimit').value='100';
 bpSocialResetDates('bpCodeAdmin');bpById('bpCodeAdminSave').textContent='➕ コードを発行';
}
function bpSocialNewsClear(){
 bpById('bpNewsAdminId').value='';bpById('bpNewsAdminTitle').value='';bpById('bpNewsAdminBody').value='';
 bpById('bpNewsAdminImportant').checked=false;bpSocialResetDates('bpNewsAdmin');
