function bpSocialAdminControls(target,onEdit,onStop){
 const actions=bpSocialNode('div','bp180Row');
 const edit=bpSocialNode('button','','✏️ 編集'),stop=bpSocialNode('button','','⏹ 中止');
 edit.type=stop.type='button';edit.onclick=onEdit;stop.onclick=onStop;
