function bpSocialRenderCodes(){
 const container=bpById('bpCodeAdminList');container.replaceChildren();
 if(!bpSocialCodes.length){container.appendChild(bpSocialNode('div','bp180Card','コードはまだ発行されていないよ'));return}
 bpSocialCodes.forEach(v=>{
  const card=bpSocialNode('div','bp180Card');card.appendChild(bpSocialNode('strong','bp180CodeResult',v.code));
  card.appendChild(bpSocialNode('div','bp180Note',(v.enabled?'🟢':'⏹')+' '+(v.note||'メモなし')+' ｜ 🪙'+v.coins+' ｜ '+v.claimed+' / '+v.maxUses+'人'));
  card.appendChild(bpSocialNode('div','bp180Note',bpSocialDateText(v.startsAt)+' 〜 '+bpSocialDateText(v.endsAt)));
  if(v.enabled)bpSocialAdminControls(card,()=>bpSocialCodeFill(v),async()=>{
   if(!confirm('このプレゼントコードを中止する？'))return;
   try{await bpSocialApi('/api/social/admin/codes',{admin:true,body:{action:'stop',id:v.id}});await bpSocialLoadCodes();}
   catch(e){bpSocialMsg('bpCodeAdminStatus','⚠️ '+e.message)}
  });container.appendChild(card);
 });
}
function bpSocialRenderNews(items,targetId,isAdmin=false){
 const container=bpById(targetId);container.replaceChildren();
 if(!items.length){container.appendChild(bpSocialNode('div','bp180Card',isAdmin?'管理中のお知らせはないよ':'📭 今のお知らせはまだないよ'));return}
 for(const v of items){
  const row=bpSocialNode('div','bp180Notice'+(v.important?' important':''));
