  row.appendChild(bpSocialNode('div','bp180NoticeTime',bpSocialDateText(v.startsAt)+' 〜 '+bpSocialDateText(v.endsAt)+(isAdmin?(v.enabled?' ｜ 配信設定中':' ｜ 中止済み'):'')));
