async function bpSocialRedeem(){
 if(bpSocialBusy)return;const code=bpById('bpRedeemText').value.trim().toUpperCase();
 if(!/^[A-Z0-9-]{6,24}$/.test(code)){bpSocialMsg('bpRedeemStatus','⚠️ コードは英数字6〜24文字だよ');return}
 const playerId=playerRandomId();if(!playerId){bpSocialMsg('bpRedeemStatus','⚠️ プレイヤーIDを準備できなかったよ');return}
 bpSocialBusy=true;bpById('bpRedeemBtn').disabled=true;bpSocialMsg('bpRedeemStatus','📡 コードを確認しているよ…');
 try{
  const result=await bpSocialApi('/api/social/redeem',{body:{code,playerId}});
  const key='blockpop_social_code_ledger_v1';let ledger={};try{ledger=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{}
  const grant=!ledger[code]&&Number.isInteger(result.coins)&&result.coins>0;
  if(grant){coins+=result.coins;saveCoins();ledger[code]=true;localStorage.setItem(key,JSON.stringify(ledger));renderShop();}
  bpSocialMsg('bpRedeemStatus',grant?'🎉 コード受取成功！ 🪙'+result.coins+'コイン GET！':'✅ このコードは受け取り済みだよ');
  if(grant)toast('🎁 🪙'+result.coins+'コイン獲得！');
 }catch(e){bpSocialMsg('bpRedeemStatus','⚠️ '+e.message)}finally{bpSocialBusy=false;bpById('bpRedeemBtn').disabled=false}
}
