// AI offline mode, independent boards and 15 moves per side.
const BP_AI_TURNS=15,BP_AI_STORAGE='blockpop_ai_history_v1';
let bpAiGame=null;
function bpAiDeal(){return Array.from({length:3},()=>({shape:SHAPES[Math.floor(Math.random()*SHAPES.length)].map(row=>row.slice()),color:1+Math.floor(Math.random()*COLORS.length),used:false}))}
function bpAiRotate(shape,rotation){let out=shape;for(let i=0;i<rotation;i++)out=out[0].map((_,c)=>out.map(r=>r[c]).reverse());return out}
function bpAiFit(board,shape,r,c){
 for(let y=0;y<shape.length;y++)for(let x=0;x<shape[y].length;x++)if(shape[y][x]){
  const yy=r+y,xx=c+x;if(yy<0||xx<0||yy>=8||xx>=8||board[yy*8+xx])return false;
 }return true;
}
function bpAiDrop(board,shape,r,c,color){
 let blocks=0;for(let y=0;y<shape.length;y++)for(let x=0;x<shape[y].length;x++)if(shape[y][x]){board[(r+y)*8+c+x]=color;blocks++}
 let rows=[],cols=[];for(let y=0;y<8;y++)if(board.slice(y*8,y*8+8).every(Boolean))rows.push(y);
 for(let x=0;x<8;x++){let full=true;for(let y=0;y<8;y++)if(!board[y*8+x])full=false;if(full)cols.push(x)}
 const removed=new Set();for(const y of rows)for(let x=0;x<8;x++)removed.add(y*8+x);
 for(const x of cols)for(let y=0;y<8;y++)removed.add(y*8+x);
 for(const i of removed)board[i]=0;
 return{score:blocks+10*(rows.length+cols.length)+removed.size,lines:rows.length+cols.length,blocks,removed:removed.size};
}
function bpAiPossible(board,pieces){for(const piece of pieces)if(!piece.used)for(let k=0;k<4;k++){
 const shape=bpAiRotate(piece.shape,k);for(let r=0;r<=8-shape.length;r++)for(let c=0;c<=8-shape[0].length;c++)if(bpAiFit(board,shape,r,c))return true;
 }return false}
function bpAiCpuTurn(){const game=bpAiGame;if(!game||game.done)return;
 let best=null;for(let p=0;p<game.cpuPieces.length;p++){
  const piece=game.cpuPieces[p];if(piece.used)continue;
  for(let rot=0;rot<4;rot++){
   const shape=bpAiRotate(piece.shape,rot);
   for(let r=0;r<=8-shape.length;r++)for(let c=0;c<=8-shape[0].length;c++){
    if(!bpAiFit(game.cpu,shape,r,c))continue;
    const simulation=game.cpu.slice(),result=bpAiDrop(simulation,shape,r,c,piece.color);
    const remaining=simulation.filter(v=>!v).length;
    const value=result.score*4+result.lines*35+remaining*.13+Math.random()*3;
    if(!best||value>best.value)best={p,rot,r,c,value,shape};
   }
  }
 }
 if(!best){bpAiFinish('🤖 CPUが置けるブロックを失ったよ');return}
 const piece=game.cpuPieces[best.p];const result=bpAiDrop(game.cpu,best.shape,best.r,best.c,piece.color);
 game.cpuScore+=result.score;piece.used=true;
 if(game.cpuPieces.every(p=>p.used))game.cpuPieces=bpAiDeal();
}
function bpAiHistory(){try{return JSON.parse(localStorage.getItem(BP_AI_STORAGE)||'{}')||{}}catch{return {}}}
function bpAiFinish(reason='15手終了！'){
 const game=bpAiGame;if(!game||game.done)return;game.done=true;
 const win=game.playerScore>game.cpuScore,draw=game.playerScore===game.cpuScore;
 const data=bpAiHistory();data.games=(data.games||0)+1;data.wins=(data.wins||0)+(win?1:0);
 data.draws=(data.draws||0)+(draw?1:0);data.best=Math.max(data.best||0,game.playerScore);
 try{localStorage.setItem(BP_AI_STORAGE,JSON.stringify(data))}catch{}
 game.message=reason+' '+(draw?'🤝 引き分け！':win?'🏆 あなたの勝ち！':'🤖 CPUの勝ち！');
 bpAiRender();
}
function bpAiMove(index){
 const game=bpAiGame;if(!game||game.done)return;const piece=game.playerPieces[game.selected];if(!piece||piece.used)return;
 const shape=bpAiRotate(piece.shape,game.rotation),r=Math.floor(index/8),c=index%8;
 if(!bpAiFit(game.player,shape,r,c)){game.message='❌ そこには置けないよ。左上のマスを選んでね';bpAiRender();return}
 const result=bpAiDrop(game.player,shape,r,c,piece.color);game.playerScore+=result.score;piece.used=true;
 game.turns++;if(game.playerPieces.every(p=>p.used))game.playerPieces=bpAiDeal();
 game.selected=game.playerPieces.findIndex(p=>!p.used);game.rotation=0;
 bpAiCpuTurn();if(game.done)return;
 if(game.turns>=BP_AI_TURNS){bpAiFinish('🏁 '+BP_AI_TURNS+'手の対戦が終了！');return}
 if(!bpAiPossible(game.player,game.playerPieces)){bpAiFinish('置けるブロックがなくなったよ');return}
 game.message='🎮 あなたの番！ あと'+(BP_AI_TURNS-game.turns)+'手';bpAiRender();
}
function bpAiCells(boardId,arr,interactive){const parent=bpById(boardId);parent.replaceChildren();
 for(let i=0;i<64;i++){
  const btn=bpSocialNode('button','bp180Cell'+(arr[i]?' on':''));btn.type='button';
  if(arr[i])btn.style.background=colorCSS(COLORS[arr[i]-1]||COLORS[0]);
  if(interactive){btn.setAttribute('aria-label',(Math.floor(i/8)+1)+'行'+(i%8+1)+'列に配置');btn.onclick=()=>bpAiMove(i)}
  else btn.disabled=true;parent.appendChild(btn);
 }
}
function bpAiRender(){const game=bpAiGame;
 if(!game){bpById('bpAiStatus').textContent='「新しい試合」でスタート！';bpAiCells('bpAiPlayerBoard',Array(64).fill(0),false);bpAiCells('bpAiCpuBoard',Array(64).fill(0),false);bpById('bpAiPieces').replaceChildren();bpById('bpAiScoreYou').textContent='あなた 0点';bpById('bpAiScoreCpu').textContent='CPU 0点'}
 else{
  bpById('bpAiStatus').textContent=game.message;
  bpById('bpAiScoreYou').textContent='あなた '+game.playerScore+'点';bpById('bpAiScoreCpu').textContent='CPU '+game.cpuScore+'点';
  bpAiCells('bpAiPlayerBoard',game.player,!game.done);bpAiCells('bpAiCpuBoard',game.cpu,false);
  const list=bpById('bpAiPieces');list.replaceChildren();
  game.playerPieces.forEach((p,i)=>{
   const btn=bpSocialNode('button','bp180Piece'+(game.selected===i?' chosen':''));btn.type='button';
   btn.disabled=!!p.used||game.done;
   btn.appendChild(bpSocialNode('span','',p.used?'使用済み':'ブロック '+(i+1)));
